-- # Databricks Demo: Lakehouse Essentials (SQL version)
-- Covers: namespaces, ingestion, Delta internals, CTAS, optimization, compute.
--
-- **Requirements:** Unity Catalog workspace.
-- Sample data is generated by this notebook in SQL. Sections 2f and 2g are walkthroughs that need our own cloud bucket and Salesforce access.
--
-- If you cannot create catalogs, find and replace `demo.sales` and `/Volumes/demo/sales/` with a catalog and schema you can use.

-- ---------------------------------------------------------------------
-- ## 1. Introduction: the three-level namespace `catalog.schema.object`
-- ---------------------------------------------------------------------

CREATE CATALOG IF NOT EXISTS demo;
CREATE SCHEMA IF NOT EXISTS demo.sales;
CREATE VOLUME IF NOT EXISTS demo.sales.raw;
USE demo.sales;

SHOW CATALOGS;

SHOW SCHEMAS IN demo;

-- Fully qualified names look like `demo.sales.orders`. Open **Catalog Explorer** to show permissions, lineage and sample data.
--
-- ## Generate sample data (pure SQL)
-- `INSERT OVERWRITE DIRECTORY` writes query results as files into the volume. Each batch goes to its own folder.

INSERT OVERWRITE DIRECTORY '/Volumes/demo/sales/raw/orders/batch1'
USING CSV OPTIONS (header 'true')
SELECT /*+ COALESCE(1) */
  id AS order_id,
  CAST(1 + pmod(hash(id, 'c'), 50) AS INT) AS customer_id,
  element_at(array('Laptop', 'Phone', 'Headphones', 'Monitor', 'Keyboard'), CAST(1 + pmod(hash(id, 'p'), 5) AS INT)) AS product,
  CAST(element_at(array(900, 600, 120, 250, 60), CAST(1 + pmod(hash(id, 'p'), 5) AS INT)) * (1 + pmod(hash(id, 'q'), 3)) AS INT) AS amount,
  element_at(array('NEW', 'PAID', 'SHIPPED'), CAST(1 + pmod(hash(id, 's'), 3) AS INT)) AS status,
  date_add(DATE'2026-01-01', CAST(pmod(hash(id, 'd'), 60) AS INT)) AS order_date
FROM range(1, 501) AS t(id);

LIST '/Volumes/demo/sales/raw/orders/batch1';

-- ---------------------------------------------------------------------
-- ## 2. Data ingestion methods
-- ---------------------------------------------------------------------

-- ### 2a. UI upload
-- In the sidebar choose **+ New > Add or upload data** to upload a CSV into a table (show this live).
-- ### 2b. `read_files` (query files directly)

SELECT * FROM read_files('/Volumes/demo/sales/raw/orders/*/*.csv', format => 'csv', header => true) LIMIT 10;

-- ###`read_files` for unstructured files (images)
-- `read_files` also reads **binary** files with `format => 'binaryFile'`. Instead of inferring columns, every file becomes **one row** with a fixed schema: `path`, `modificationTime`, `length` and `content` (the raw bytes as BINARY). This works for any file type: images, PDFs, audio.
--
-- Combine it with AI functions to actually *understand* the content:
-- * `ai_query` — send the bytes to a vision model (describe, classify, extract)
-- * `ai_parse_document` — extract structured fields from images and PDFs
--
-- **Videos:** `binaryFile` reads a video file's raw bytes, but no built-in function processes video directly. Extract frames into image files first, or use `ai_transcribe` for the audio track.

-- ### 2c. Load files into a Delta table (CTAS over `read_files`)
-- `CREATE TABLE AS SELECT` on top of `read_files` loads all the files into a managed Delta table in one statement.

CREATE OR REPLACE TABLE demo.sales.orders_bronze AS
SELECT * FROM read_files('/Volumes/demo/sales/raw/orders/*/*.csv', format => 'csv', header => true);

SELECT COUNT(*) AS rows_loaded FROM demo.sales.orders_bronze;

-- ### 2d. Append new files with `INSERT INTO ... SELECT`
-- A second batch of files arrives. We point `read_files` at only the new folder and append.

INSERT OVERWRITE DIRECTORY '/Volumes/demo/sales/raw/orders/batch2'
USING CSV OPTIONS (header 'true')
SELECT /*+ COALESCE(1) */
  id AS order_id,
  CAST(1 + pmod(hash(id, 'c'), 50) AS INT) AS customer_id,
  element_at(array('Laptop', 'Phone', 'Headphones', 'Monitor', 'Keyboard'), CAST(1 + pmod(hash(id, 'p'), 5) AS INT)) AS product,
  CAST(element_at(array(900, 600, 120, 250, 60), CAST(1 + pmod(hash(id, 'p'), 5) AS INT)) * (1 + pmod(hash(id, 'q'), 3)) AS INT) AS amount,
  element_at(array('NEW', 'PAID', 'SHIPPED'), CAST(1 + pmod(hash(id, 's'), 3) AS INT)) AS status,
  date_add(DATE'2026-01-01', CAST(pmod(hash(id, 'd'), 60) AS INT)) AS order_date
FROM range(501, 701) AS t(id);

INSERT INTO demo.sales.orders_bronze
SELECT * FROM read_files('/Volumes/demo/sales/raw/orders/batch2/*.csv', format => 'csv', header => true);

SELECT COUNT(*) AS rows_loaded FROM demo.sales.orders_bronze;

