SELECT * FROM read_files('/Volumes/demo/sales/raw/orders/formats/json') LIMIT 5;
SELECT * FROM read_files('/Volumes/demo/sales/raw/orders/formats/parquet') LIMIT 5;

-- 2e load all formats into one table
-- One Delta table fed by four different file formats
CREATE OR REPLACE TABLE demo.sales.orders_formats AS
SELECT 'json' AS source_format, order_id, customer_id, product, amount, status, CAST(order_date AS DATE) AS order_date
FROM read_files('/Volumes/demo/sales/raw/orders/formats/json')
UNION ALL
SELECT 'parquet', order_id, customer_id, product, amount, status, CAST(order_date AS DATE) AS order_date
FROM read_files('/Volumes/demo/sales/raw/orders/formats/parquet')
UNION ALL
SELECT 'orc', order_id, customer_id, product, amount, status, CAST(order_date AS DATE) AS order_date
FROM read_files('/Volumes/demo/sales/raw/orders/formats/orc')
UNION ALL
SELECT 'avro', order_id, customer_id, product, amount, status, CAST(order_date AS DATE) AS order_date
FROM read_files('/Volumes/demo/sales/raw/orders/formats/avro');

-- 2e verify rows per format
SELECT source_format, COUNT(*) AS rows_loaded
FROM demo.sales.orders_formats
GROUP BY source_format
ORDER BY source_format;

SELECT * FROM demo.sales.orders_formats LIMIT 5;

