CREATE OR REPLACE TABLE demo.sales.orders AS
SELECT order_id, customer_id, product, amount, status, CAST(order_date AS DATE) AS order_date
FROM demo.sales.orders_bronze;

SELECT * FROM demo.sales.orders LIMIT 5;

-- ---------------------------------------------------------------------
-- ## 3. Delta Lake internals
-- ---------------------------------------------------------------------

-- ### How Delta stores a table in cloud storage
-- A Delta table is just a directory in cloud storage (S3, ADLS or GCS) holding two kinds of things: **immutable Parquet data files** and a **`_delta_log`** folder. The log, not the data files, is the source of truth: a table at version N is defined by replaying the log up to commit N.
--
-- **Directory layout**
-- <table root>/
-- ├── part-00000-...snappy.parquet     <- data files (immutable, written once)
-- └── _delta_log/
--     ├── 00000000000000000000.json          <- commit 0 (transaction log entry)
--     ├── 00000000000000000000.json.crc      <- checksum sidecar for commit 0
--     ├── 00000000000000000001.json          <- commit 1
--     ├── 00000000000000000010.checkpoint.parquet   <- checkpoint every 10 commits
--     └── _last_checkpoint                    <- tiny JSON pointer to newest checkpoint
--
-- **1. Commit files (`N.json`) — the transaction log**
-- One small JSON file per table version, named by zero-padded version number. A commit is atomic: the file is written with put-if-absent semantics, so a version either fully exists or does not exist at all — that is what makes Delta ACID on cheap object storage. Each file lists **actions**, and each action type contains:
-- * `add` — a new data file now part of the table: path, size, partition values, and **per-file stats** (min/max/null counts per column) that later queries use for data skipping without reading the file
-- * `remove` — a data file made obsolete by this commit, with a deletion timestamp. The Parquet file is not deleted yet, only unlinked — that is what makes time travel possible until `VACUUM` runs
-- * `metaData` — the table definition: schema, partition columns, table id, table properties
-- * `protocol` — minimum reader/writer feature versions a client must support
-- * `commitInfo` — who/what/when: operation (WRITE, UPDATE, MERGE, ...), timestamps, user, and operation metrics (rows written, files touched)
--
-- **2. Checkpoint files (`.checkpoint.parquet`)**
-- Replaying thousands of JSON commits would get slow, so every 10 commits (`delta.checkpointInterval`) Delta writes a Parquet checkpoint that summarizes the **entire current log state** — the full list of live `add` files, `metaData` and `protocol` — up to that version. To open a table, a reader loads the latest checkpoint plus only the few JSON commits after it. `_last_checkpoint` is a tiny JSON file pointing at the newest checkpoint (version, file count).
--
-- **3. CRC files (`.crc`)**
-- Every commit and checkpoint file has a sidecar `.crc` file holding a **CRC32 checksum** of that log file (plus its length). Delta uses these during log retention and cleanup to detect **corrupted or truncated log files** — for example a half-written commit left behind by a failed cloud upload. It is integrity checking for the log itself, not validation of your table data. If a checksum does not match, Delta knows the log entry is untrustworthy.
--
-- **Why this design matters**
-- * **ACID on object storage:** concurrent writers commit by atomically creating the next `N.json`; losers of a race retry (optimistic concurrency control).
-- * **Time travel:** `VERSION AS OF N` simply replays the log to commit N; the older data files are still in cloud storage until `VACUUM`.
-- * **Fast reads:** per-file min/max stats in `add` actions let queries skip whole files (data skipping) and stream readers process only new commits.

DESCRIBE DETAIL demo.sales.orders;

-- 3. describe / describe extended variants
DESCRIBE demo.sales.orders;

DESCRIBE EXTENDED demo.sales.orders;

UPDATE demo.sales.orders SET status = 'SHIPPED' WHERE order_id = 1;

DELETE FROM demo.sales.orders WHERE order_id = 2;

DESCRIBE HISTORY demo.sales.orders;

-- Time travel and restore. On a fresh run, version 0 is the original table, 1 is after the UPDATE and 2 is after the DELETE. Check the history above if yours differs.

SELECT * FROM demo.sales.orders VERSION AS OF 1 WHERE order_id IN (1, 2);

RESTORE TABLE demo.sales.orders TO VERSION AS OF 1;

-- ### Look inside the table
-- The `_metadata` column shows which Parquet files hold the rows. These are the data files that the `_delta_log` commits add and remove.

SELECT _metadata.file_path, _metadata.file_size, COUNT(*) AS rows_in_file
FROM demo.sales.orders
GROUP BY _metadata.file_path, _metadata.file_size;

-- `VACUUM` deletes unreferenced files older than the retention period (7 days by default), which limits time travel.

VACUUM demo.sales.orders DRY RUN;

-- ---------------------------------------------------------------------
-- ## 4. CTAS: CREATE TABLE AS SELECT
-- ---------------------------------------------------------------------

CREATE OR REPLACE TABLE demo.sales.daily_revenue
COMMENT 'Gold: daily revenue'
AS
SELECT order_date, SUM(amount) AS revenue, COUNT(*) AS orders
FROM demo.sales.orders
GROUP BY order_date;

SELECT * FROM demo.sales.daily_revenue ORDER BY order_date LIMIT 10;

-- `CREATE OR REPLACE` is atomic and keeps table history. Compare with a clone:

CREATE OR REPLACE TABLE demo.sales.orders_clone SHALLOW CLONE demo.sales.orders;

SELECT COUNT(*) AS rows_in_clone FROM demo.sales.orders_clone;

-- ---------------------------------------------------------------------
-- ## 5. Optimization
-- ---------------------------------------------------------------------

-- Create a table with many small files. The `REPARTITION` hint forces many output files. Optimized writes on your workspace may merge some of them, so check the file count.

CREATE OR REPLACE TABLE demo.sales.orders_small AS
SELECT /*+ REPARTITION(40) */ * FROM demo.sales.orders;

INSERT INTO demo.sales.orders_small SELECT /*+ REPARTITION(40) */ * FROM demo.sales.orders;

DESCRIBE DETAIL demo.sales.orders_small;

OPTIMIZE demo.sales.orders_small;

DESCRIBE DETAIL demo.sales.orders_small;

-- `numFiles` drops after `OPTIMIZE`. Now Liquid Clustering for data skipping:

CREATE OR REPLACE TABLE demo.sales.orders_clustered CLUSTER BY (customer_id, order_date) AS
SELECT * FROM demo.sales.orders_small;

OPTIMIZE demo.sales.orders_clustered;

describe detail demo.sales.orders_clustered

-- 5. describe table / show create table (clustering keys)
DESCRIBE TABLE demo.sales.orders_clustered;


SHOW CREATE TABLE demo.sales.orders_clustered;

SELECT COUNT(*) AS orders, SUM(amount) AS revenue
FROM demo.sales.orders_clustered
WHERE customer_id = 7;

-- ---------------------------------------------------------------------
-- ## 6. Compute
-- ---------------------------------------------------------------------

-- | Type | Use for |
-- |---|---|
-- | All-purpose cluster | Interactive notebooks and development |
-- | Job compute | Scheduled production workflows, cheaper and ephemeral |
-- | SQL warehouse (Classic, Pro, Serverless) | SQL, BI and dashboards |
-- | Serverless compute | Notebooks, jobs and pipelines with no cluster management |
--
-- **Live walkthrough**
-- 1. Open **Compute > Create compute** and show runtime version, node type, autoscaling, auto-termination, Photon and spot instances.
-- 2. Show access modes (standard vs dedicated) and cluster policies.
-- 3. Open **SQL Warehouses** and show size, scaling and auto-stop.
--
-- Check what this notebook is running on:![db-guide_compute.webp](./db-guide_compute.webp "db-guide_compute.webp")![simple-form.png](./simple-form.png "simple-form.png")

SELECT current_version() AS runtime, current_user() AS user_name, current_catalog() AS catalog_name;


SELECT
  CASE
    WHEN current_version().dbr_version IS NOT NULL THEN 'Classic cluster (DBR ' || current_version().dbr_version || ')'
    WHEN current_version().dbsql_version IS NOT NULL THEN 'Serverless / SQL warehouse'
    ELSE 'Unknown'
  END AS compute_type,
  current_version().dbsql_version AS version;


  SELECT compute, statement_text, start_time
FROM system.query.history
ORDER BY start_time DESC
LIMIT 5;

